CREATE TABLE users(id UUID PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE employees(id UUID PRIMARY KEY,user_id UUID NOT NULL UNIQUE REFERENCES users(id),employee_code VARCHAR(100) NOT NULL UNIQUE,first_name VARCHAR(120) NOT NULL,last_name VARCHAR(120) NOT NULL,phone VARCHAR(50),department VARCHAR(120),designation VARCHAR(120),manager_name VARCHAR(200),joining_date DATE,date_of_birth DATE,address VARCHAR(500),emergency_contact VARCHAR(200),basic_salary NUMERIC(14,2) DEFAULT 0,onboarding_complete BOOLEAN NOT NULL DEFAULT FALSE); CREATE TABLE attendance(id UUID PRIMARY KEY,employee_id UUID NOT NULL REFERENCES employees(id),work_date DATE NOT NULL,check_in TIMESTAMP,check_out TIMESTAMP,status VARCHAR(40) NOT NULL,notes VARCHAR(1000),CONSTRAINT uq_attendance UNIQUE(employee_id,work_date)); CREATE TABLE leave_requests(id UUID PRIMARY KEY,employee_id UUID NOT NULL REFERENCES employees(id),type VARCHAR(40) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,reason VARCHAR(1000) NOT NULL,status VARCHAR(40) NOT NULL,reviewer_comment VARCHAR(1000),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE payroll(id UUID PRIMARY KEY,employee_id UUID NOT NULL REFERENCES employees(id),payroll_month VARCHAR(7) NOT NULL,basic NUMERIC(14,2) NOT NULL,allowances NUMERIC(14,2) NOT NULL,deductions NUMERIC(14,2) NOT NULL,net_pay NUMERIC(14,2) NOT NULL,status VARCHAR(40) NOT NULL,processed_at TIMESTAMP,CONSTRAINT uq_payroll UNIQUE(employee_id,payroll_month)); CREATE TABLE performance_reviews(id UUID PRIMARY KEY,employee_id UUID NOT NULL REFERENCES employees(id),review_year INTEGER NOT NULL,rating NUMERIC(4,2),strengths VARCHAR(4000),improvement_areas VARCHAR(4000),manager_feedback VARCHAR(4000),review_date DATE); CREATE TABLE holidays(id UUID PRIMARY KEY,name VARCHAR(255) NOT NULL,date DATE NOT NULL,optional_holiday BOOLEAN NOT NULL DEFAULT FALSE);